export const SREC_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/srec-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSrecStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SREC_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
